/**
 * Default environment for new DeereClient instances when config.environment
 * is not specified. 'sandboxapi' is safe-by-default — never silently hits
 * production data.
 */
export const DEFAULT_ENVIRONMENT: Environment = 'sandboxapi';

// ============================================================================
// SpecServerConfig — per-spec URL resolution config
// ============================================================================

/**
 * A path served from a different base than its own spec declares.
 *
 * Deere does this: `GET /notifications/{sourceEvent}` lives on `/isg` while
 * the other three operations in the same document live on `/platform`.
 * Sourced from path-level `servers` in specs/fixed, written there by
 * scripts/routing-overrides.yaml, which requires measured evidence per entry.
 */
export interface PathServerOverride {
  /** Path pattern; a `{param}` segment matches any single segment. */
  pattern: string;
  /** URL template with `{environment}` placeholder. */
  urlTemplate: string;
  /**
   * The environments this path item's servers block lists. Written by
   * fix-specs from scripts/routing-overrides.yaml, as the union of what the
   * templated specs declare. Recorded, not enforced: see the templated config.
   */
  supportedEnvironments: readonly Environment[];
}

export type SpecServerConfig =
  | {
      kind: 'templated';
      /** URL template with `{environment}` placeholder. */
      urlTemplate: string;
      /**
       * The environments the spec's servers block lists
       * (servers.variables.environment.enum in specs/fixed). John Deere
       * declares the list for a spec whose own servers block is a template.
       * For one that hard-codes platform hosts, or that declares no servers
       * and is given a block by scripts/routing-overrides.yaml, fix-specs
       * writes it: the union of the lists the others declare.
       *
       * Recorded, not enforced. The resolver substitutes whatever environment
       * the client was built with, in the list or not.
       */
      supportedEnvironments: readonly Environment[];
      /**
       * Paths that override the template above. Absent for most specs, where
       * every path shares the document's base. Checked before `urlTemplate`.
       */
      pathOverrides?: readonly PathServerOverride[];
    }
  | {
      kind: 'static';
      /**
       * PARTIAL map — envs we can't confidently serve are OMITTED. Runtime
       * throws UnsupportedEnvironmentError on missing keys. See
       * scripts/generate-api-servers.ts for the env-to-tier classifier.
       */
      urlByEnvironment: Readonly<Partial<Record<Environment, string>>>;
    }
  | {
      kind: 'unavailable';
      /** Human-readable explanation for diagnostics. */
      reason: string;
    };

